  tools.exec_command({cmd:"sed -n '1,220p' gost/debian_test.go && sed -n '1,140p' gost/ubuntu_test.go",workdir:"/app",max_output_tokens:7000}),
  tools.exec_command({cmd:"sed -n '1,130p' detector/detector_test.go && sed -n '1,100p' go.mod",workdir:"/app",max_output_tokens:7000}),
  tools.exec_command({cmd:"grep -R -n 'RedHatAPIMatch\\|RedHatAPI' detector gost models | head -100",workdir:"/app",max_output_tokens:3500})
]); for (const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

